head.script:
// 테스트 설명, 유효성 값 설정
// 담당 범위(3개 분할 중 _1) : displayMode 값별 입력창, 리스트창 표시 형식 / 구분자 / 바인딩된 DataCollection 저장값
//  - _2 : 편집 상태의 입력창 (searchTarget, displayModeSync)
//  - _3 : 선택 안내, 전체 선택 아이템 / GridViewItemSet 리스트창
scwin.tData = {
    "description" : "[autoComplete > P > displayMode]<br/>AutoComplete 컴포넌트의 입력창과 아이템 리스트창에 아이템이 표시되는 형식을 설정합니다.",
    "validation" : [
        "label 설정 시, 아이템의 Label 을 표시합니다.",
        "미설정 시, 아이템의 Label 을 표시합니다.",
        "value 설정 시, 아이템의 Value 를 표시합니다.",
        "value delim label 설정 시, 아이템의 Value 와 Label 을 구분자로 구분하여 순서대로 표시합니다.",
        "label delim value 설정 시, 아이템의 Label 과 Value 를 구분자로 구분하여 순서대로 표시합니다.",
        "구분자는 delimiter 속성값을 사용하며 해당 속성을 설정하지 않으면 Tab('\\t')이 적용됩니다.",
        "displayMode 형식은 화면 표시에만 적용되며 바인딩된 DataCollection 에는 아이템의 Value 가 저장됩니다.",
    ]
}

// 표시값 확인 버튼을 누르는 시점의 리스트창 아이템
scwin.gVar = { "arrItem" : [] };



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // target1 의 Value 가 저장될 DataMap 생성 (ref 바인딩 대상)
    let strDm = '';
    strDm += '<w2:dataMap ' + $c.gcm.getNameSpace() + ' baseNode="map" id="dm_ref">';
    strDm += '<w2:keyInfo>';
    strDm += '<w2:key id="city" name="city" dataType="text"></w2:key>';
    strDm += '</w2:keyInfo>';
    strDm += '</w2:dataMap>';
    $p.data.create(strDm);

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    con_displayMode.setValue("value delim label");
    con_delimiter.setValue(":");

    // 표시값 확인 버튼 클릭 시 목록이 먼저 닫히므로 mousedown capture 단계에서 리스트창 아이템을 기록
    btn_getDisplayInfo.render.addEventListener("mousedown", scwin.captureListState, true);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제]\n- 아이템(Label / Value) : 서울 / SEL, 부산 / BSN, 대구 / DGU, 인천 / ICN\n- Target 은 DataMap(dm_ref) 의 city 에 바인딩\n[절차]\n1. 화살표 버튼으로 목록을 연 상태에서 표시값 확인\n2. 목록에서 아이템 선택 -> 표시값 확인\n[확인] 결과창의 Tab 구분자는 [TAB] 으로 표기"', '', 'label1');

    // DataMap 값 초기화
    dm_ref.set("city", "");

    // 미설정 옵션은 createCList 가 속성에서 제외
    let properties = {
        ref : "data:dm_ref.city",
        displayMode : con_displayMode.getValue(),
        delimiter : con_delimiter.getValue(),
    }

    let cList = $c.gcm.createCList(properties);

    let strTarget = '';
    strTarget += '<w2:autoComplete ' + $c.gcm.getNameSpace() + ' ' + cList + ' style="width:200px; height:30px;">';
    strTarget += '<w2:choices>';
    strTarget += '<w2:item><w2:label>서울</w2:label><w2:value>SEL</w2:value></w2:item>';
    strTarget += '<w2:item><w2:label>부산</w2:label><w2:value>BSN</w2:value></w2:item>';
    strTarget += '<w2:item><w2:label>대구</w2:label><w2:value>DGU</w2:value></w2:item>';
    strTarget += '<w2:item><w2:label>인천</w2:label><w2:value>ICN</w2:value></w2:item>';
    strTarget += '</w2:choices>';
    strTarget += '</w2:autoComplete>';

    await $p.dynamicCreate("target1", "autoComplete", strTarget, $c.gcm.getTestGroup());
}



// Tab 구분자를 판별할 수 있도록 [TAB] 으로 치환하고 따옴표로 감싸 공백 구분자 확인
scwin.escapeText = function (str) {
    return "'" + String(str).split("\t").join("[TAB]") + "'";
}



// 버튼 mousedown 시점(목록이 닫히기 전)의 리스트창 표시 아이템 기록
scwin.captureListState = function (e) {
    scwin.gVar.arrItem = [];

    let itemTableElem = document.querySelector("[id='" + target1.id + "_itemTable']");
    if (!itemTableElem) {
        return;
    }
    let objStyle = getComputedStyle(itemTableElem);
    if (objStyle.display === "none" || objStyle.visibility === "hidden") {
        return;
    }

    // 숨겨진 Row 는 제외하고 화면에 보이는 아이템만 수집
    let rowList = itemTableElem.querySelectorAll("[id='" + target1.id + "_itemTable_main'] tr");
    for (let i = 0; i < rowList.length; i++) {
        if (rowList[i].offsetHeight > 0) {
            scwin.gVar.arrItem.push(scwin.escapeText(rowList[i].textContent));
        }
    }
};



// 리스트창 아이템, 입력창 표시 텍스트, 바인딩된 DataMap 값 출력
scwin.btn_getDisplayInfo_onclick = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");

    // validation 1 ~ 6 : 열린 리스트창의 아이템 표시 형식
    if (scwin.gVar.arrItem.length > 0) {
        bottom.setReturnValue("리스트창 아이템 : " + scwin.gVar.arrItem.join(" / "));
    }

    // validation 1 ~ 6, 7 : 선택된 아이템의 입력창 표시 형식과 바인딩된 DataMap 저장값
    let labelElem = document.querySelector("[id='" + target1.id + "_label']");
    if (labelElem.textContent !== "") {
        bottom.setReturnValue("입력창 표시 텍스트 : " + scwin.escapeText(labelElem.textContent) + " / DataMap(dm_ref) city 값 : " + scwin.escapeText(dm_ref.get("city")));
    }
};
